function c00_simple_if(a: boolean, b: boolean, c: boolean, d: boolean): boolean { if (a) return true; return false; }
function c01_nested_if(a: boolean, b: boolean, c: boolean, d: boolean): boolean { if (a) { if (b) return true; } return false; }
function c02_triple_nested_if(a: boolean, b: boolean, c: boolean, d: boolean): boolean { if (a) { if (b) { if (c) return true; } } return false; }
function c03_if_else(a: boolean, b: boolean, c: boolean, d: boolean): boolean { if (a) return true; else return false; return false; }
function c04_if_elif_else(a: boolean, b: boolean, c: boolean, d: boolean): boolean { if (a) return true; else if (b) return false; else return true; return false; }
function c05_three_way_chain(a: boolean, b: boolean, c: boolean, d: boolean): boolean { if (a) return true; else if (b) return false; else if (c) return true; else return false; return false; }
function c06_and_sequence(a: boolean, b: boolean, c: boolean, d: boolean): boolean { if (a && b) return true; return false; }
function c07_or_sequence(a: boolean, b: boolean, c: boolean, d: boolean): boolean { if (a || b) return true; return false; }
function c08_mixed_boolean(a: boolean, b: boolean, c: boolean, d: boolean): boolean { if (a && b || c && d) return true; return false; }
function c09_assigned_boolean(a: boolean, b: boolean, c: boolean, d: boolean): boolean { const value = a && b; return value; return false; }
function c10_while_loop(a: boolean, b: boolean, c: boolean, d: boolean): boolean { while (a) { a = false; } return false; }
function c11_for_loop(a: boolean, b: boolean, c: boolean, d: boolean): boolean { for (const item of [a, b]) { void item; } return false; }
function c12_if_with_loop(a: boolean, b: boolean, c: boolean, d: boolean): boolean { if (a) { for (const item of [b, c]) { void item; } } return false; }
function c13_nested_loops(a: boolean, b: boolean, c: boolean, d: boolean): boolean { for (const item of [a, b]) { while (item) { break; } } return false; }
function c14_switch_or_match(a: boolean, b: boolean, c: boolean, d: boolean): boolean { switch (a) { case true: return true; default: return false; } return false; }
function c15_switch_nested_if(a: boolean, b: boolean, c: boolean, d: boolean): boolean { switch (a) { case true: if (b) return true; break; default: return false; } return false; }
function c16_try_one_catch(a: boolean, b: boolean, c: boolean, d: boolean): boolean { try { if (a) return true; } catch (error) { return false; } return false; }
function c17_try_two_catches(a: boolean, b: boolean, c: boolean, d: boolean): boolean { try { if (a) return true; } catch (error) { if (b) return false; } return false; }
function c18_recursive_call(a: boolean, b: boolean, c: boolean, d: boolean): boolean { if (a) return true; return c18_recursive_call(b, a); return false; }
function c19_conditional_expression(a: boolean, b: boolean, c: boolean, d: boolean): boolean { return a ? true : false; return false; }
function c20_nested_conditionals(a: boolean, b: boolean, c: boolean, d: boolean): boolean { return a ? true : (b ? false : true); return false; }
function c21_lambda_decision(a: boolean, b: boolean, c: boolean, d: boolean): boolean { return [a].some(value => { if (value) return true; return false; }); return false; }
function c22_if_lambda_decision(a: boolean, b: boolean, c: boolean, d: boolean): boolean { if (a) return [b].some(value => { if (value) return true; return false; }); return false; }
function c23_nested_callable(a: boolean, b: boolean, c: boolean, d: boolean): boolean { function inner() { if (a) return true; return false; } return inner(); return false; }
function c24_try_finally(a: boolean, b: boolean, c: boolean, d: boolean): boolean { try { if (a) return true; } finally { cleanup(); } return false; }
function c25_labeled_jump(a: boolean, b: boolean, c: boolean, d: boolean): boolean { outer: while (a) { break outer; } return false; }
function c26_boolean_operator_sequences(a: boolean, b: boolean, c: boolean, d: boolean): boolean { return a && (b || c); }
function c27_language_idiom(a: boolean, b: boolean, c: boolean, d: boolean): boolean { for (const item of [a, b]) { if (item) return true; } return false; }
function c28_loop_if_boolean(a: boolean, b: boolean, c: boolean, d: boolean): boolean { for (const item of [a, b]) { if (item && a) return true; } return false; }
function c29_else_loop(a: boolean, b: boolean, c: boolean, d: boolean): boolean { if (a) return true; else { while (b) { break; } } return false; }
